'use client';
import { Fragment, useEffect, useLayoutEffect, useRef, useState, type CSSProperties, type ReactNode } from 'react';
import { cx } from '../lib/cx';
import { useControllable, useReducedMotion, useSeconds } from '../lib/hooks';
import { Icon, type IconName } from '../lib/icons';
import { enter, Fold, Swap } from '../lib/motion';
import '../designme.css';
import './agent-lanes.css';

export type LaneStatus = 'queued' | 'waiting' | 'working' | 'paused' | 'done';
export type LaneTone = 'blue' | 'purple' | 'green' | 'orange' | 'red' | 'yellow' | 'pink' | 'teal';

export interface AgentLane {
  key: string;
  /** Like "Researcher" */
  name: string;
  icon: IconName;
  /** The lane's hue: its badge, its track, its Working tag and its stretch of the relay line. Defaults to blue */
  tone?: LaneTone;
  /** working breathes, shimmers and fills the next step, paused holds it, done fills the badge with its hue */
  status: LaneStatus;
  /** What the agent is doing now, or what it is waiting for. It crossfades when it changes, and shimmers while the agent works */
  activity: string;
  /** How many steps the track is cut into. Defaults to 3 */
  steps?: number;
  /** How many steps are finished. The next one fills while the agent works */
  done?: number;
  /** How far the agent is through the step in hand, from 0 to 1. Leave it out and that step fills part way */
  progress?: number;
  /** What the agent did, shown when the lane is opened. New entries slide in */
  log?: { text: string; time?: string }[];
}

/** One agent passing work to another: a light runs down the relay line between their badges, with a line saying what changed hands */
export interface AgentHandoff {
  /** Key of the lane handing over */
  from: string;
  /** Key of the lane taking it */
  to: string;
  /** What changes hands, like "the brief" */
  what: string;
}

export interface AgentLanesProps {
  lanes: AgentLane[];
  /** Header text. Defaults to "3 agents working", "All agents paused" or "All 3 agents finished" */
  title?: string;
  /** Seconds to show as m:ss. Leave it out to let the header count while agents work */
  seconds?: number;
  /** Whether every agent is paused. Working lanes then show Paused and the clock stops */
  paused?: boolean;
  defaultPaused?: boolean;
  /** Adds the Pause all / Resume button, until every lane is done */
  onPausedChange?: (paused: boolean) => void;
  /** The handoff to show. Set it back to undefined and its line slides away; the stretch of relay line it crossed stays lit */
  handoff?: AgentHandoff;
  /** Keys of the lanes that are open. Leave it out to let each row toggle itself */
  expanded?: string[];
  defaultExpanded?: string[];
  onExpandedChange?: (keys: string[]) => void;
  /** Sits flat in a chat thread (the default, as on designme.dev). Set false to give it a card of its own */
  bare?: boolean;
  className?: string;
}

const TONE: Record<LaneTone, string> = { blue: 'pb', purple: 'pl', green: 'pm', orange: 'pp', red: 'pr', yellow: 'py', pink: 'pk', teal: 'pt' };
const hue = (l?: AgentLane) => TONE[l?.tone ?? 'blue'];

/** How many times `value` has changed since the first render, so a part can play its entrance on a change but not on mount */
function useChanges<T>(value: T) {
  const [seen, setSeen] = useState({ value, n: 0 });
  if (Object.is(seen.value, value)) return seen.n;
  setSeen({ value, n: seen.n + 1 });
  return seen.n + 1;
}

/** Keeps the last value on screen for `ms` after it is cleared, so it can play its exit */
function usePresence<T>(value: T | undefined, ms = 700) {
  const [kept, setKept] = useState(value);
  if (value !== undefined && value !== kept) setKept(value);
  useEffect(() => {
    if (value !== undefined || kept === undefined) return;
    const t = setTimeout(() => setKept(undefined), ms);
    return () => clearTimeout(t);
  }, [value, kept, ms]);
  return { shown: value ?? kept, leaving: value === undefined && kept !== undefined };
}

/** The hand-off line: it mounts shut and opens on the next frame, so the lanes below glide down, then closes before it goes */
function Handoff({ leaving, lit, style, children }: { leaving: boolean; lit: boolean; style: CSSProperties; children: ReactNode }) {
  const [open, setOpen] = useState(false);
  useEffect(() => { let b = 0; const a = requestAnimationFrame(() => { b = requestAnimationFrame(() => setOpen(true)); }); return () => { cancelAnimationFrame(a); cancelAnimationFrame(b); }; }, []);
  const e = enter(80);
  return (
    <div className={cx('dm-fold dm-aln-hf', !(open && !leaving) && 'dm-shut', lit && 'dm-lit')} style={style} inert={!(open && !leaving)} aria-hidden={!(open && !leaving)}>
      <div><div className={cx('dm-aln-hand', e.className)} style={e.style}>{children}</div></div>
    </div>
  );
}

function StatusTag({ status }: { status: LaneStatus }) {
  const moved = useChanges(status) > 0 ? 'dm-enter' : undefined;
  if (status === 'working') return <span key="working" className={cx('dm-tag dm-aln-tg', moved)}><span className="dm-spin" aria-hidden="true" />Working</span>;
  if (status === 'paused') return <span key="paused" className={cx('dm-tag dm-warn', moved)}>Paused</span>;
  if (status === 'done') return <span key="done" className={cx('dm-tag dm-ok', moved)}><Icon name="check" size="xs" />Done</span>;
  if (status === 'waiting') return <span key="waiting" className={cx('dm-tag', moved)}><Icon name="clock" size="xs" />Waiting</span>;
  return <span key="queued" className={cx('dm-tag', moved)}>Queued</span>;
}

function Lane({ lane, paused, open, sent, got, ping, onToggle }: { lane: AgentLane; paused: boolean; open: boolean; sent: boolean; got: boolean; ping: boolean; onToggle: () => void }) {
  const status = paused && lane.status === 'working' ? 'paused' : lane.status;
  const tone = hue(lane), steps = lane.steps ?? 3, done = lane.done ?? 0;
  const live = status === 'working' || status === 'paused';
  return (
    <div className={cx('dm-aln-lane', sent && 'dm-sent', got && 'dm-got')} data-s={status} data-lane={lane.key} style={{ '--dm-c': `var(--dm-${tone})`, '--dm-cb': `var(--dm-${tone}-bg)`, '--dm-cm': `var(--dm-aln-${tone},var(--dm-${tone}))` } as CSSProperties}>
      <button type="button" className="dm-aln-row" aria-expanded={open} onClick={onToggle}>
        <span className={cx('dm-aln-av', ping && 'dm-ping')}>
          <Icon name={lane.icon} />
        </span>
        <span className="dm-aln-who"><span className="dm-aln-n">{lane.name}</span><Swap className={cx('dm-aln-a', live && 'dm-live', status === 'working' && 'dm-shim')}>{lane.activity}</Swap></span>
        <span className="dm-aln-tr" aria-hidden="true">
          {Array.from({ length: steps }, (_, i) => {
            const run = i === done && live;
            return <i key={i} className={cx(i < done && 'dm-on', run && 'dm-run', run && lane.progress === undefined && 'dm-ind')}
              style={run && lane.progress !== undefined ? { '--dm-p': Math.max(0, Math.min(1, lane.progress)) } as CSSProperties : undefined} />;
          })}
        </span>
        <span className="dm-aln-st"><StatusTag status={status} /></span>
      </button>
      <Fold open={open}>
        <div className="dm-aln-det">
          {lane.log?.map((l, i) => <div key={i} className="dm-enter"><span>{l.text}</span>{l.time && <span className="dm-muted">{l.time}</span>}</div>)}
        </div>
      </Fold>
    </div>
  );
}

const clock = (s: number) => `${Math.floor(s / 60)}:${String(s % 60).padStart(2, '0')}`;

/** Several agents working side by side, each in its own lane and hue, handing work to one another down a relay line. */
export function AgentLanes({ lanes, title, seconds, paused, defaultPaused = false, onPausedChange, handoff, expanded, defaultExpanded = [], onExpandedChange, bare = true, className }: AgentLanesProps) {
  const [isPaused, setPaused] = useControllable(paused, defaultPaused, onPausedChange);
  const [open, setOpen] = useControllable(expanded, defaultExpanded, onExpandedChange);
  const finished = lanes.length > 0 && lanes.every(l => l.status === 'done');
  const counted = useSeconds(seconds === undefined && !isPaused && !finished);
  const { shown: hand, leaving } = usePresence(handoff);
  const reduce = useReducedMotion();
  const rows = useRef<HTMLDivElement>(null);
  // the hand-offs whose light has arrived: their stretch of the relay line stays lit, drawn by the stroke that carried it
  const [relayed, setRelayed] = useState<string[]>([]);
  const [drawing, setDrawing] = useState<string>();
  const [ping, setPing] = useState<string>();
  const handKey = hand ? `${hand.from}>${hand.to}` : '';
  // the line opens first, then the relay line draws itself from the sender's badge down to the taker's, in the gap between
  // them, so nothing passes over a badge
  useEffect(() => {
    if (!handoff) return;
    const key = `${handoff.from}>${handoff.to}`;
    if (relayed.includes(key)) return;
    const t = window.setTimeout(() => setDrawing(key), reduce ? 0 : 500);
    return () => clearTimeout(t);
  }, [handoff?.from, handoff?.to]); // eslint-disable-line react-hooks/exhaustive-deps
  // each lit stroke is one line from badge to badge that follows them as the lanes move (a hand-off line opening or shutting,
  // a lane folding open), so there is never a second line under it
  const strokes = drawing && !relayed.includes(drawing) ? [...relayed, drawing] : relayed;
  useLayoutEffect(() => {
    const box = rows.current; if (!box) return;
    const place = () => {
      const rr = box.getBoundingClientRect();
      box.querySelectorAll<HTMLElement>(':scope>.dm-aln-pk').forEach(pk => {
        const [f, g] = (pk.dataset.k ?? '').split('>');
        const a = box.querySelector(`[data-lane="${CSS.escape(f)}"] .dm-aln-av`), b = box.querySelector(`[data-lane="${CSS.escape(g)}"] .dm-aln-av`);
        if (!a || !b) return;
        const y0 = a.getBoundingClientRect().bottom - rr.top + 4, y1 = b.getBoundingClientRect().top - rr.top - 4;
        pk.style.top = y0 + 'px'; pk.style.height = Math.max(0, y1 - y0) + 'px';
      });
    };
    place();
    const ro = new ResizeObserver(place); ro.observe(box);
    return () => ro.disconnect();
  }, [strokes.join(), lanes.length]);
  useLayoutEffect(() => {
    if (!drawing) return;
    const pk = rows.current?.querySelector<HTMLElement>(`:scope>.dm-aln-pk[data-k="${CSS.escape(drawing)}"]`);
    const key = drawing, to = key.split('>')[1];
    let t2 = 0;
    const arrive = () => { setRelayed(r => r.includes(key) ? r : [...r, key]); setDrawing(d => d === key ? undefined : d); setPing(to); t2 = window.setTimeout(() => setPing(p => p === to ? undefined : p), 950); };
    if (!pk || reduce) { arrive(); return () => clearTimeout(t2); }
    const an = pk.animate([{ transform: 'scaleY(0)' }, { transform: 'scaleY(1)' }], { duration: 800, easing: 'cubic-bezier(.65,0,.35,1)' });
    an.finished.then(arrive, () => {});
    return () => { clearTimeout(t2); };
  }, [drawing]); // eslint-disable-line react-hooks/exhaustive-deps

  const nameOf = (key: string) => lanes.find(l => l.key === key)?.name ?? key;
  const toneOf = (key: string) => hue(lanes.find(l => l.key === key));
  const head = title ?? (finished ? `All ${lanes.length} agents finished` : isPaused ? 'All agents paused' : `${lanes.length} agents working`);
  const total = lanes.reduce((n, l) => n + (l.steps ?? 3), 0), stepsDone = lanes.reduce((n, l) => n + Math.min(l.done ?? 0, l.steps ?? 3), 0);

  return (
    <div data-dm="" className={cx('dm-aln', !bare && 'dm-panel', finished && 'dm-fin', className)} style={bare ? { paddingInline: 0 } : undefined}>
      <div className="dm-aln-h">
        <span className="dm-aln-ic">{finished ? <span key="ok" {...enter()} style={{ display: 'grid' }}><Icon name="ok" /></span> : <Icon name="users" />}</span>
        <Swap className="dm-aln-t">{head}</Swap>
        <span className="dm-aln-m dm-muted dm-num">{clock(seconds ?? counted)}</span>
        <Swap className="dm-aln-ct dm-num">{`${stepsDone} of ${total} steps`}</Swap>
        {onPausedChange && !finished && (
          <button type="button" className="dm-pill dm-soft dm-sm" onClick={() => setPaused(!isPaused)}>
            <Icon name={isPaused ? 'play' : 'pause'} size="xs" />{isPaused ? 'Resume' : 'Pause all'}
          </button>
        )}
      </div>
      <div className="dm-aln-rows" ref={rows}>
        {lanes.map(l => (
          <Fragment key={l.key}>
            {hand?.to === l.key && (
              <Handoff key={handKey} leaving={leaving} lit={relayed.includes(handKey)} style={{ '--dm-from': `var(--dm-${toneOf(hand.from)})`, '--dm-to': `var(--dm-${toneOf(hand.to)})` } as CSSProperties}>
                <b className="dm-f">{nameOf(hand.from)}</b> handed {hand.what} to <b className="dm-t">{nameOf(hand.to)}</b>
              </Handoff>
            )}
            <Lane lane={l} paused={isPaused} open={open.includes(l.key)} ping={ping === l.key}
              sent={relayed.some(k => k.startsWith(l.key + '>'))} got={relayed.some(k => k.endsWith('>' + l.key))}
              onToggle={() => setOpen(open.includes(l.key) ? open.filter(k => k !== l.key) : [...open, l.key])} />
          </Fragment>
        ))}
        {strokes.map(k => {
          const [f, g] = k.split('>');
          return <span key={k} className="dm-aln-pk" data-k={k} aria-hidden="true" style={{ '--dm-from': `var(--dm-aln-${toneOf(f)},var(--dm-${toneOf(f)}))`, '--dm-to': `var(--dm-aln-${toneOf(g)},var(--dm-${toneOf(g)}))` } as CSSProperties} />;
        })}
      </div>
    </div>
  );
}

/* Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync. */
/* ---------- Agent lanes ---------- */
/* each agent has its own hue (--dm-c, with its tint --dm-cb): its badge, its track, its tag and its stretch of the relay line that
   joins the badges. A hand-off sends a light down that line from one agent to the next, and the stretch it crossed stays lit */
.dm-aln{padding:var(--dm-s-2)}
/* the lanes' marks (tracks, lines, a finished badge) in livelier versions of the agents' hues, each 3:1 on the surface; their
   text keeps the agent's text colour. Dark mode's agent colours are light already, so they are used as they are */
.dm-aln{--dm-aln-pb:#2a7bff;--dm-aln-pm:#1fa66a;--dm-aln-pl:#7a5af5}
@media (prefers-color-scheme:dark){:root:not([data-theme="light"]) .dm-aln{--dm-aln-pb:var(--dm-pb);--dm-aln-pm:var(--dm-pm);--dm-aln-pl:var(--dm-pl)}}
:root[data-theme="dark"] .dm-aln{--dm-aln-pb:var(--dm-pb);--dm-aln-pm:var(--dm-pm);--dm-aln-pl:var(--dm-pl)}
/* on a card the lanes sit centred in the room kept for their tallest moment, and glide as a hand-off line opens and shuts */
.dm-stage-in:has(>.dm-aln){display:flex;flex-direction:column;justify-content:center}
.dm-aln-h{display:flex;align-items:center;gap:10px;padding:var(--dm-s-2) 10px 10px}
.dm-aln-ic{color:var(--dm-fg2);display:grid;transition:color .3s}
.dm-aln.dm-fin .dm-aln-ic{color:var(--dm-ok)}
.dm-aln-t{font-weight:500}
.dm-aln-m{font-size:12.5px}
.dm-aln-ct{font-size:12.5px;color:var(--dm-muted);margin-right:auto;white-space:nowrap}
.dm-aln-ct::before{content:"·";margin-right:6px}
.dm-aln-rows{position:relative}
.dm-aln-rows>*{position:relative}
.dm-aln-lane{border-radius:calc(14px * var(--dm-rk));transition:background .3s}
@media (hover:hover) and (pointer:fine){.dm-aln-lane:hover{background:var(--dm-row)}}
/* the lane at work carries a wash of its hue from the left */
.dm-aln-lane[data-s="working"]{background:linear-gradient(90deg,color-mix(in srgb,var(--dm-c) 8%,transparent),transparent 72%)}
@media (hover:hover) and (pointer:fine){.dm-aln-lane[data-s="working"]:hover{background:linear-gradient(90deg,color-mix(in srgb,var(--dm-c) 8%,transparent),transparent 72%),var(--dm-row)}}
/* the relay line runs from badge to badge, through the lanes and the hand-offs between them, and stops short of each badge */
.dm-aln-rows>*::before{content:"";position:absolute;left:26px;width:2px;top:0;bottom:0;background:var(--dm-line);pointer-events:none}
.dm-aln-lane::before{top:48px}
.dm-aln-lane:last-child::before{display:none}
.dm-aln-lane::after{content:"";position:absolute;left:26px;width:2px;top:0;height:6px;background:var(--dm-line);pointer-events:none}
.dm-aln-lane:first-child::after{display:none}
/* a stretch that has carried a hand-off is drawn by its one lit stroke (.aln-pk, below), so the grey under it steps aside
   and the line from badge to badge stays a single clean line */
.dm-aln-rows>.dm-aln-lane.dm-sent::before,.dm-aln-rows>.dm-aln-lane.dm-got::after,.dm-aln-rows>.dm-aln-hf.dm-lit::before{background:transparent}
.dm-aln-row{display:grid;grid-template-columns:34px minmax(0,1.2fr) minmax(0,1fr) auto;align-items:center;gap:var(--dm-s-3);width:100%;padding:10px;text-align:left}
.dm-aln-av{position:relative;width:34px;height:34px;border-radius:calc(11px * var(--dm-rk));display:grid;place-items:center;color:var(--dm-c);background:var(--dm-cb);transition:color .4s,background .4s}
.dm-aln-av::before{content:"";position:absolute;inset:0;border-radius:inherit;pointer-events:none}
.dm-aln-lane[data-s="working"] .dm-aln-av{animation:dm-alnbreathe 2.4s var(--dm-ease-io) infinite}
@keyframes dm-alnbreathe{0%,100%{box-shadow:0 0 0 1px color-mix(in srgb,var(--dm-c) 22%,transparent),0 0 0 1px color-mix(in srgb,var(--dm-fg) 0%,transparent)}50%{box-shadow:0 0 0 1px color-mix(in srgb,var(--dm-c) 22%,transparent),0 0 0 5px color-mix(in srgb,var(--dm-fg) 6%,transparent)}}
/* the badge that takes a hand-off rings once as the light reaches it */
.dm-aln-av.dm-ping::before{animation:dm-alnping .9s var(--dm-ease)}
@keyframes dm-alnping{from{box-shadow:0 0 0 0 color-mix(in srgb,var(--dm-fg) 20%,transparent)}to{box-shadow:0 0 0 12px color-mix(in srgb,var(--dm-fg) 0%,transparent)}}
/* the lane at work is tinted, so what sits on the tint (its badge, its tag) is lifted onto the surface to stand clear of it */
.dm-aln-lane[data-s="working"] .dm-aln-av,.dm-aln-lane[data-s="working"] .dm-aln-tg{background:var(--dm-surface);box-shadow:0 0 0 1px color-mix(in srgb,var(--dm-c) 22%,transparent)}
/* a finished agent's badge fills with its hue */
.dm-aln-lane[data-s="done"] .dm-aln-av{background:var(--dm-cm);color:var(--dm-surface)}
.dm-aln-who{min-width:0}
.dm-aln-n{display:block;font-weight:500;font-size:13.5px}
.dm-aln-a{display:block;font-size:12.5px;color:var(--dm-muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.dm-aln-a.dm-live{color:var(--dm-fg2)}
/* the track: one part a step. Finished parts are solid, the one in hand fills as the agent works, with a light running along it */
.dm-aln-tr{display:flex;gap:3px}
.dm-aln-tr i{flex:1;height:10px;border-radius:5px;background:color-mix(in srgb,var(--dm-cm) 13%,var(--dm-line));position:relative;overflow:hidden}
.dm-aln-tr i::after{content:"";position:absolute;inset:0;border-radius:inherit;background:var(--dm-cm);transform:scaleX(var(--dm-p,0));transform-origin:left;transition:transform .25s linear}
.dm-aln-tr i.dm-on::after{transform:scaleX(1);transition:transform .5s var(--dm-ease)}
.dm-aln-tr i.dm-run::after{background:linear-gradient(90deg,var(--dm-cm) 0 30%,color-mix(in srgb,var(--dm-cm) 30%,var(--dm-surface)) 50%,var(--dm-cm) 70% 100%) 0 0/250% 100%;animation:dm-alnsheen 1.6s linear infinite}
/* given no step progress, the part in hand fills part way and keeps its light */
.dm-aln-tr i.dm-run.dm-ind::after{transform:scaleX(.6);transition:transform 2.4s var(--dm-ease)}
@keyframes dm-alnsheen{from{background-position:100% 0}to{background-position:-150% 0}}
.dm-aln-st{min-width:92px;display:flex;justify-content:flex-end}
.dm-aln-tg{background:var(--dm-cb);color:var(--dm-c)}
.dm-aln-tg .dm-spin{width:9px;height:9px}
.dm-aln-det{padding:0 10px 10px 56px;font-size:12.5px;color:var(--dm-fg2)}
.dm-aln-det div{display:flex;align-items:center;gap:var(--dm-s-2);padding:3px 0}
.dm-aln-det div::before{content:"";width:5px;height:5px;border-radius:50%;background:var(--dm-c);flex:none}
.dm-aln-det .dm-muted{margin-left:auto}
/* a hand-off opens a line between the lanes, glides the lanes below down and closes again */
.dm-aln-hf{transition-duration:var(--dm-t-slow)}
.dm-aln-hand{padding:6px 10px 6px 56px;font-size:12.5px;line-height:18px;color:var(--dm-fg2)}
.dm-aln-hand b{font-weight:500}
.dm-aln-hand .dm-f{color:var(--dm-from)}.dm-aln-hand .dm-t{color:var(--dm-to)}
/* the hand-off draws the relay line from the sender's badge down to the taker's, in the gap between them (it never passes
   over a badge): a stroke that fills from the sender's hue into the taker's, then stays as the lit stretch (owner, 4 Nov).
   It is one element from badge to badge that follows them as the lanes move, so there is never a second line under it */
.dm-aln-rows>.dm-aln-pk::before{display:none}
.dm-aln-pk{position:absolute;left:26px;top:0;width:2px;background:linear-gradient(var(--dm-from),var(--dm-to));transform-origin:50% 0;pointer-events:none;z-index:2}
@media (max-width:600px){
  .dm-aln-row{grid-template-columns:34px minmax(0,1fr) auto;row-gap:var(--dm-s-2)}
  .dm-aln-tr{grid-column:2 / -1;grid-row:2}
  .dm-aln-lane::before{top:48px}
  .dm-aln-ct{display:none}
  .dm-aln-m{margin-right:auto}
}
@media (max-width:400px){.dm-aln-ic{display:none}}
:root:not([data-style="soft"]) .dm-aln-rows>*:not(:where([data-style="soft"],[data-style="soft"] *))::before,:root:not([data-style="soft"]) .dm-aln-lane:not(:where([data-style="soft"],[data-style="soft"] *))::after{width:1px;left:26.5px;background:repeating-linear-gradient(var(--dm-rail) 0 3px,transparent 3px 6px)}
:root:not([data-style="soft"]) .dm-aln-rows>.dm-aln-lane.dm-sent:not(:where([data-style="soft"],[data-style="soft"] *))::before,:root:not([data-style="soft"]) .dm-aln-rows>.dm-aln-lane.dm-got:not(:where([data-style="soft"],[data-style="soft"] *))::after,:root:not([data-style="soft"]) .dm-aln-rows>.dm-aln-hf.dm-lit:not(:where([data-style="soft"],[data-style="soft"] *))::before{background:transparent}
:root:not([data-style="soft"]) .dm-aln-lane[data-s="working"] :is(.dm-aln-av,.dm-aln-tg):not(:where([data-style="soft"],[data-style="soft"] *)){box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-c) 45%,transparent)}
:root:not([data-style="soft"]) .dm-aln-av:not(:where([data-style="soft"],[data-style="soft"] *)){box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-c) 35%,transparent)}
:root:not([data-style="soft"]) .dm-aln-lane[data-s="working"] .dm-aln-av:not(:where([data-style="soft"],[data-style="soft"] *)){animation:dm-alnbp 1.1s steps(1,end) infinite}
@keyframes dm-alnbp{0%,55%{box-shadow:inset 0 0 0 1px var(--dm-c)}56%,100%{box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-c) 35%,transparent)}}
:root:not([data-style="soft"]) .dm-aln-lane[data-s="working"]:not(:where([data-style="soft"],[data-style="soft"] *)){background:color-mix(in srgb,var(--dm-c) 5%,transparent)}
:root:not([data-style="soft"]) .dm-aln-tr i:not(:where([data-style="soft"],[data-style="soft"] *)){height:8px}
:root:not([data-style="soft"]) .dm-aln-tr i.dm-run:not(:where([data-style="soft"],[data-style="soft"] *))::after{background:repeating-linear-gradient(135deg,var(--dm-cm) 0 4px,color-mix(in srgb,var(--dm-cm) 55%,var(--dm-surface)) 4px 7px);animation:none}
:root:not([data-style="soft"]) .dm-aln-pk:not(:where([data-style="soft"],[data-style="soft"] *)){width:1px;left:26.5px;border-radius:0;background:var(--dm-to)}
:root:not([data-style="soft"]) .dm-aln-av.dm-ping:not(:where([data-style="soft"],[data-style="soft"] *))::before{animation:dm-alnpingbp .6s steps(3,end)}
@keyframes dm-alnpingbp{from{box-shadow:0 0 0 1px var(--dm-c)}to{box-shadow:0 0 0 7px transparent}}
